style.css:
@-moz-document domain("mail.google.com") {
/* Cambiar todos los textos a color rosado */
  * {
    color: #ff6b88 !important;
  }

  /* Cambiar fondo del botón "Redactar" */
  div[role="button"][gh="cm"] {
    background-color: #ffb2c1 !important;
    color: white !important; /* Para que el texto siga siendo legible */
    font-weight: bold !important;
  }
}
